/**
 * Shared helpers for acceptance tests.
 *
 * These utilities are imported by every test file so later sprints can
 * reuse the same registration / login / task-creation primitives without
 * duplicating code.  Each helper is deliberately stateless except for the
 * data it creates under a unique namespace (the `suffix` parameter), so
 * tests never interfere with one another even though they share the same
 * service instance.
 *
 * All tests must create their own data under unique names and never assume
 * the service starts empty — other tests' records may be present.
 */

import { expect } from '@playwright/test';

/**
 * Generate a random suffix so every test creates uniquely-named records.
 * @returns {string} A short random string.
 */
export function uniqueSuffix() {
  // 6 random hex chars → ~16M combinations, enough for test isolation.
  return Math.random().toString(16).slice(2, 8);
}

/**
 * Register a new user and return the parsed response body.
 *
 * @param {import('@playwright/test').APIRequestContext} request — Playwright request fixture.
 * @param {string} suffix — Unique suffix for this test's identity.
 * @returns {Promise<object>} Parsed JSON body of the registration response.
 */
export async function registerUser(request, suffix) {
  const username = `testuser_${suffix}`;
  const email = `${suffix}@example.com`;
  const password = 'SecurePass123!';
  const response = await request.post('/api/register', {
    data: { username, email, password },
  });
  return response;
}

/**
 * Log in a user and return the parsed JSON body containing the access token.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} email — User's email address.
 * @param {string} password — User's password.
 * @returns {Promise<object>} Parsed JSON body: `{ access_token, token_type }`.
 */
export async function loginUser(request, email, password) {
  const response = await request.post('/api/login', {
    data: { email, password },
  });
  return response;
}

/**
 * Create a task via the API and return the parsed response body.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} token — Bearer token string.
 * @param {object} options
 * @param {string} [options.title] — Task title (default "Test Task <suffix>").
 * @param {string} [options.suffix] — Unique suffix appended to title.
 * @param {string} [options.priority] — Priority value.
 * @returns {Promise<object>} Parsed JSON body of the created task.
 */
export async function createTask(request, token, { title, suffix, priority } = {}) {
  const taskTitle = title || `Test Task${suffix ? ' ' + suffix : ''}`;
  const response = await request.post('/api/tasks', {
    headers: { Authorization: `Bearer ${token}` },
    data: {
      title: taskTitle,
      priority: priority || 'medium',
      status: 'pending',
    },
  });
  return response;
}

/**
 * Get a single task by ID and return the parsed JSON body.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} token — Bearer token string.
 * @param {number} taskId — The task's numeric ID.
 * @returns {Promise<object>} Parsed JSON body of the task.
 */
export async function getTask(request, token, taskId) {
  const response = await request.get(`/api/tasks/${taskId}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return response;
}

/**
 * Update a task via PUT and return the parsed JSON body.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} token — Bearer token string.
 * @param {number} taskId — The task's numeric ID.
 * @param {object} updates — Fields to update.
 * @returns {Promise<object>} Parsed JSON body of the updated task.
 */
export async function updateTask(request, token, taskId, updates) {
  const response = await request.put(`/api/tasks/${taskId}`, {
    headers: { Authorization: `Bearer ${token}` },
    data: updates,
  });
  return response;
}

/**
 * Delete a task and return the parsed JSON body.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} token — Bearer token string.
 * @param {number} taskId — The task's numeric ID.
 * @returns {Promise<object>} Parsed JSON body.
 */
export async function deleteTask(request, token, taskId) {
  const response = await request.delete(`/api/tasks/${taskId}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return response;
}

/**
 * Complete a full registration + login cycle, returning both the response
 * objects and the access token string.
 *
 * @param {import('@playwright/test').APIRequestContext} request
 * @param {string} suffix — Unique suffix for this test's identity.
 * @returns {Promise<{registerResponse: object, loginResponse: object, token: string, email: string, password: string, username: string}>}
 */
export async function registerAndLogin(request, suffix) {
  const username = `testuser_${suffix}`;
  const email = `${suffix}@example.com`;
  const password = 'SecurePass123!';

    const registerResponse = await registerUser(request, suffix);
    expect(registerResponse.status()).toBe(201);

    const loginResponse = await loginUser(request, email, password);
    expect(loginResponse.status()).toBe(200);

  const loginBody = await loginResponse.json();
  return {
    registerResponse,
    loginResponse,
    token: loginBody.access_token,
    email,
    password,
    username,
  };
}

