/**
 * Acceptance tests for AC-12 (API documentation available).
 *
 * Verifies that the Swagger/OpenAPI documentation is served at /docs
 * and returns 200 with HTML containing 'Swagger' or 'OpenAPI'.
 */

import { test, expect } from '@playwright/test';

/**
 * [AC-12] GET /docs returns 200 with HTML containing 'Swagger' or 'OpenAPI'
 *
 * Verifies the Swagger UI is accessible without authentication and contains
 * the expected documentation markers.
 */
test('[AC-12] /docs returns Swagger/OpenAPI documentation', async ({ request }) => {
  const response = await request.get('/docs');

  expect(response.status()).toBe(200);
  expect(response.ok()).toBeTruthy();

  const contentType = response.headers()['content-type'] || '';
  expect(contentType).toContain('text/html');

  const html = await response.text();
  // Must contain either 'Swagger' or 'OpenAPI' in the HTML
  const hasSwaggerOrOpenAPI =
    html.includes('Swagger') || html.includes('OpenAPI');
  expect(hasSwaggerOrOpenAPI).toBeTruthy();
});

/**
 * [AC-12] GET /openapi.json returns valid OpenAPI schema
 *
 * Verifies the OpenAPI JSON schema is accessible without authentication.
