/**
 * Acceptance tests for AC-14 (Modern web application with responsive design).
 *
 * Verifies:
 * - The application page loads with a visible main container
 * - The page contains a valid viewport meta tag
 *
 * Uses Playwright to load the page in a real browser and assert
 * on the rendered DOM and page source.
 */

import { test, expect } from '@playwright/test';

/**
 * [AC-14] Application page loads with visible main container
 *
 * Verifies that the root React app renders a main element
 * that is visible in the DOM.
 */
test('[AC-14] main container is visible on page load', async ({ page }) => {
  const errors = [];
  page.on('pageerror', (error) => errors.push(error.message));

  await page.goto('/');

  // The main container should be visible
  const mainEl = page.getByRole('main');
  await expect(mainEl).toBeVisible();

  // The page should have a heading
  const heading = page.getByRole('heading', { level: 1 });
  await expect(heading).toBeVisible();

  // No uncaught errors during page load
  expect(errors).toEqual([]);
});

/**
 * [AC-14] Page contains a valid viewport meta tag
 *
 * Verifies that the HTML response includes a viewport meta tag
 * with width=device-width and initial-scale=1.
 */
test('[AC-14] viewport meta tag is present', async ({ page }) => {
  await page.goto('/');

  // Check the viewport meta tag exists in the page source
  const viewportMeta = page.locator('meta[name="viewport"]');
  await expect(viewportMeta).toHaveCount(1);

  const content = await viewportMeta.getAttribute('content');
  expect(content).toContain('width=device-width');
  expect(content).toContain('initial-scale=1');
});

/**
 * [AC-14] Page renders without console errors
 *
 * Verifies that the page loads without JavaScript console errors,
 * which would indicate broken functionality.
 */
test('[AC-14] page loads without console errors', async ({ page }) => {
  const consoleErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') {
      consoleErrors.push(msg.text());
    }
  });

  await page.goto('/');
  await page.waitForTimeout(500);

  expect(consoleErrors).toEqual([]);
});

/**
 * [AC-14] Page title is set
 *
 * Verifies that the page has a meaningful title.
 */
test('[AC-14] page has a title', async ({ page }) => {
  await page.goto('/');

  const title = await page.title();
  expect(title).toBe('Task Management Dashboard');
});

